//go:build spec

package metrics

import (
	"context"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/metrics/metricstest"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// Plan 3, stream 3. Contract assumed by these tests:
//
//	New() *Registry                 a private prometheus.Registry inside
//	(*Registry).Handler() http.Handler   the /metrics handler, no auth
//	(*Registry).WatchDatabase(db)   registers the scrape-time gauges
//	Catalog() []Series              the one table New registers from
//	Series{Name, Kind string; Labels []string}

// golden is section 3.1 of the plan. A change here is a change to the
// dashboards and alerts, so it must be deliberate.
var golden = []Series{
	{"generation_duration_seconds", "histogram", []string{"outcome"}},
	{"http_requests_total", "counter", []string{"route", "status"}},
	{"llm_request_duration_seconds", "histogram", []string{"stage"}},
	{"llm_requests_total", "counter", []string{"outcome", "stage"}},
	{"llm_tokens_total", "counter", []string{"direction", "stage"}},
	{"llm_validation_failures_total", "counter", []string{"rule", "stage"}},
	{"messages", "gauge", []string{"channel", "state"}},
	{"messages_total", "counter", []string{"channel", "outcome"}},
	{"provider_request_duration_seconds", "histogram", []string{"channel"}},
	{"provider_requests_total", "counter", []string{"channel", "class"}},
	{"queue_jobs", "gauge", []string{"queue", "state"}},
	{"queue_oldest_job_age_seconds", "gauge", []string{"queue"}},
	{"rate_limiter_wait_seconds", "histogram", []string{"channel"}},
	{"retries_total", "counter", []string{"channel", "reason"}},
	{"sse_streams", "gauge", nil},
	{"worker_last_processed_timestamp_seconds", "gauge", nil},
}

func normalized(in []Series) []Series {
	out := make([]Series, len(in))
	for i, s := range in {
		labels := slices.Clone(s.Labels)
		slices.Sort(labels)
		out[i] = Series{Name: s.Name, Kind: s.Kind, Labels: labels}
	}
	slices.SortFunc(out, func(a, b Series) int { return strings.Compare(a.Name, b.Name) })
	return out
}

func TestCatalogIsGolden(t *testing.T) {
	got, want := normalized(Catalog()), normalized(golden)
	if len(got) != len(want) {
		t.Errorf("%d series, want %d", len(got), len(want))
	}
	for i := 0; i < len(got) && i < len(want); i++ {
		g, w := got[i], want[i]
		if g.Name != w.Name || g.Kind != w.Kind || !slices.Equal(g.Labels, w.Labels) {
			t.Errorf("series %d: %+v, want %+v", i, g, w)
		}
	}
	for _, s := range got {
		for _, l := range s.Labels {
			if strings.Contains(l, "id") {
				t.Errorf("%s has label %q: labels are closed sets, never ids", s.Name, l)
			}
		}
		if s.Kind == "counter" && !strings.HasSuffix(s.Name, "_total") {
			t.Errorf("counter %s does not end in _total", s.Name)
		}
	}
}

// Nothing but catalog series (and the histogram suffixes) is exposed.
func TestHandlerExposesOnlyCatalog(t *testing.T) {
	r := New()
	known := map[string]bool{}
	for _, s := range Catalog() {
		known[s.Name] = true
		if s.Kind == "histogram" {
			for _, suf := range []string{"_bucket", "_sum", "_count"} {
				known[s.Name+suf] = true
			}
		}
	}
	for _, n := range metricstest.Scrape(t, r.Handler()).Names() {
		if !known[n] && !strings.HasPrefix(n, "go_") && !strings.HasPrefix(n, "process_") {
			t.Errorf("exposed series %s is not in the catalog", n)
		}
	}
}

// Database gauges are read at scrape time and cover every campaign.
func TestDatabaseGaugesMatchRows(t *testing.T) {
	url, _ := testdb.Seeded(t)
	ctx := context.Background()
	p, err := pgxpool.New(ctx, url)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(p.Close)

	users := userIDs(t, p, 6)
	a, b := sendingCampaign(t, p), sendingCampaign(t, p)
	rows := []struct {
		c       [2]string
		user    string
		channel string
		state   string
	}{
		{a, users[0], "sms", "sent"},
		{a, users[1], "sms", "sent"},
		{a, users[2], "sms", "queued"},
		{a, users[0], "email", "failed"},
		{b, users[3], "sms", "sent"},
		{b, users[4], "email", "sent"},
		{b, users[5], "email", "dead"},
	}
	for _, r := range rows {
		var id string
		if err := p.QueryRow(ctx, `INSERT INTO messages (campaign_id, revision_id, user_id, channel) VALUES ($1, $2, $3, $4) RETURNING id::text`,
			r.c[0], r.c[1], r.user, r.channel).Scan(&id); err != nil {
			t.Fatal(err)
		}
		if r.state != "queued" {
			if _, err := p.Exec(ctx, `UPDATE messages SET state = $2::text, attempts = 1, first_attempt_at = now(),
				sent_at = CASE WHEN $2::text = 'sent' THEN now() END,
				provider_message_id = CASE WHEN $2::text = 'sent' THEN 'p-' || id::text END,
				last_error_class = CASE WHEN $2::text IN ('failed', 'dead') THEN 'client_error'::text END
				WHERE id = $1`, id, r.state); err != nil {
				t.Fatalf("set %s: %v", r.state, err)
			}
		}
	}

	// Two available jobs on the sms queue, the older one 120 s old.
	for i := range 2 {
		if _, err := p.Exec(ctx, `INSERT INTO river_job (kind, queue, state, args, max_attempts, priority, created_at, scheduled_at)
			VALUES ('send', 'sms', 'available', '{}', 25, 1, now() - make_interval(secs => $1), now())`, 120-i*60); err != nil {
			t.Fatal(err)
		}
	}

	reg := New()
	reg.WatchDatabase(p)
	s := metricstest.Scrape(t, reg.Handler())
	for _, w := range []struct {
		channel, state string
		n              float64
	}{
		{"sms", "sent", 3}, {"sms", "queued", 1}, {"email", "sent", 1}, {"email", "failed", 1}, {"email", "dead", 1},
	} {
		if got := s.Get("messages", "channel="+w.channel, "state="+w.state); got != w.n {
			t.Errorf("messages{%s,%s} = %v, want %v", w.channel, w.state, got, w.n)
		}
	}
	if got := s.Get("queue_jobs", "queue=sms", "state=available"); got != 2 {
		t.Errorf("queue_jobs{sms,available} = %v, want 2", got)
	}
	if age := s.Get("queue_oldest_job_age_seconds", "queue=sms"); age < 120 || age > 120+30 {
		t.Errorf("queue_oldest_job_age_seconds{sms} = %v, want about 120", age)
	}
	for _, v := range s.LabelValues() {
		if metricstest.IDShaped(v) {
			t.Errorf("label value %q looks like an id", v)
		}
	}

	// Gauges follow the database, not process activity.
	if _, err := p.Exec(ctx, `UPDATE messages SET state = 'sent', sent_at = now(), provider_message_id = 'p-late'
		WHERE campaign_id = $1 AND state = 'queued'`, a[0]); err != nil {
		t.Fatal(err)
	}
	s = metricstest.Scrape(t, reg.Handler())
	if got := s.Get("messages", "channel=sms", "state=sent"); got != 4 {
		t.Errorf("after an update: messages{sms,sent} = %v, want 4", got)
	}
}

// A scrape does not hang on a slow database: the collector has its own
// 2 s timeout.
func TestDatabaseGaugesTimeout(t *testing.T) {
	url, _ := testdb.Seeded(t)
	ctx := context.Background()
	p, err := pgxpool.New(ctx, url)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(p.Close)
	lock, err := p.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer lock.Rollback(ctx)
	if _, err := lock.Exec(ctx, `LOCK TABLE messages IN ACCESS EXCLUSIVE MODE`); err != nil {
		t.Fatal(err)
	}
	reg := New()
	reg.WatchDatabase(p)
	start := time.Now()
	_ = metricstest.Scrape(t, reg.Handler())
	if d := time.Since(start); d > 4*time.Second {
		t.Errorf("scrape took %v under a locked table, want about 2 s", d)
	}
}

func userIDs(t *testing.T, p *pgxpool.Pool, n int) []string {
	t.Helper()
	rows, err := p.Query(context.Background(), `SELECT id::text FROM users WHERE consent_sms AND consent_email ORDER BY id LIMIT $1`, n)
	if err != nil {
		t.Fatal(err)
	}
	ids, err := pgx.CollectRows(rows, pgx.RowTo[string])
	if err != nil || len(ids) != n {
		t.Fatalf("users: %d %v", len(ids), err)
	}
	return ids
}

// sendingCampaign returns a campaign id and its approved revision id.
func sendingCampaign(t *testing.T, p *pgxpool.Pool) [2]string {
	t.Helper()
	ctx := context.Background()
	var c [2]string
	if err := p.QueryRow(ctx, `INSERT INTO campaigns (brief, campaign_url) VALUES ('b', 'https://shop.example/k') RETURNING id::text`).Scan(&c[0]); err != nil {
		t.Fatal(err)
	}
	if err := p.QueryRow(ctx, `INSERT INTO campaign_revisions (campaign_id, n, source, segment, sms_body, email_subject, email_body)
		VALUES ($1, 1, 'llm', '{"version":1,"match":"all","conditions":[]}', 'sms', 'subject', 'body') RETURNING id::text`, c[0]).Scan(&c[1]); err != nil {
		t.Fatal(err)
	}
	if _, err := p.Exec(ctx, `UPDATE campaigns SET state = 'sending', version = 3, current_revision_id = $2,
		approved_revision_id = $2, approved_by = 'fixture', approved_at = now() WHERE id = $1`, c[0], c[1]); err != nil {
		t.Fatal(err)
	}
	return c
}
//go:build spec

// Package metricstest scrapes a /metrics handler and reads the Prometheus
// text format, so tests check what a scraper sees without importing the
// client library. It is built only with the spec tag until stream 3 lands.
package metricstest

import (
	"bufio"
	"net/http"
	"net/http/httptest"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// Samples maps a series key, name{k="v",...} with labels sorted, to its
// value.
type Samples map[string]float64

var line = regexp.MustCompile(`^([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{(.*)\})? (\S+)(?: \d+)?$`)
var label = regexp.MustCompile(`([a-zA-Z_][a-zA-Z0-9_]*)="((?:[^"\\]|\\.)*)"`)

// Scrape GETs h with no Authorization header and parses the answer.
func Scrape(t testing.TB, h http.Handler) Samples {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/metrics", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("/metrics: %d %s", rec.Code, rec.Body)
	}
	return Parse(t, rec.Body.String())
}

// Parse reads the text exposition format.
func Parse(t testing.TB, text string) Samples {
	t.Helper()
	out := Samples{}
	sc := bufio.NewScanner(strings.NewReader(text))
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		l := sc.Text()
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		m := line.FindStringSubmatch(l)
		if m == nil {
			t.Fatalf("not a sample line: %q", l)
		}
		v, err := strconv.ParseFloat(m[3], 64)
		if err != nil {
			t.Fatalf("sample %q: %v", l, err)
		}
		var labels []string
		for _, lm := range label.FindAllStringSubmatch(m[2], -1) {
			labels = append(labels, lm[1]+"="+lm[2])
		}
		out[Key(m[1], labels...)] = v
	}
	return out
}

// Key builds a series key from a name and "k=v" labels in any order.
func Key(name string, labels ...string) string {
	if len(labels) == 0 {
		return name
	}
	s := slices.Clone(labels)
	slices.Sort(s)
	parts := make([]string, len(s))
	for i, kv := range s {
		k, v, _ := strings.Cut(kv, "=")
		parts[i] = k + `="` + v + `"`
	}
	return name + "{" + strings.Join(parts, ",") + "}"
}

// Get returns a series value, 0 when it is absent (a counter not yet
// incremented is not exposed).
func (s Samples) Get(name string, labels ...string) float64 { return s[Key(name, labels...)] }

// Has reports whether a series is exposed.
func (s Samples) Has(name string, labels ...string) bool {
	_, ok := s[Key(name, labels...)]
	return ok
}

// Delta returns after minus before for one series.
func Delta(before, after Samples, name string, labels ...string) float64 {
	return after.Get(name, labels...) - before.Get(name, labels...)
}

// LabelValues returns every label value of every series.
func (s Samples) LabelValues() []string {
	var out []string
	for k := range s {
		for _, lm := range label.FindAllStringSubmatch(k, -1) {
			out = append(out, lm[2])
		}
	}
	return out
}

// Names returns the metric names of every series, histogram suffixes
// included.
func (s Samples) Names() []string {
	seen := map[string]bool{}
	for k := range s {
		name, _, _ := strings.Cut(k, "{")
		seen[name] = true
	}
	out := make([]string, 0, len(seen))
	for n := range seen {
		out = append(out, n)
	}
	slices.Sort(out)
	return out
}

// idShaped matches UUIDs and long digit runs: campaign, message and user
// ids must never be label values.
var idShaped = regexp.MustCompile(`[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-|^\d{5,}$`)

// IDShaped reports whether a label value looks like an id.
func IDShaped(v string) bool { return idShaped.MatchString(v) }

//go:build spec

package httpapi

import (
	"context"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/metrics"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/metrics/metricstest"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// Plan 3, 3.2 and 3.4: GET /metrics is served outside auth, and
// http_requests_total labels its route by the mux pattern, never by the
// path, so no id becomes a label value.
func TestMetricsEndpoint(t *testing.T) {
	url, meta := testdb.Seeded(t)
	p := pool(t, url)
	reg := metrics.New()
	h := handler(t, &Server{
		Config:  Config{AdminToken: token, CampaignURLHosts: []string{"shop.example"}},
		Pool:    p,
		Now:     func() time.Time { return meta.AsOf },
		Metrics: reg,
	})

	f := insertCampaign(t, p, "in_review", 1)
	if rec := do(h, "GET", "/api/campaigns/"+f.ID, "", bearer); rec.Code != http.StatusOK {
		t.Fatalf("get: %d", rec.Code)
	}
	if rec := do(h, "GET", "/api/campaigns/"+unknown, "", bearer); rec.Code != http.StatusNotFound {
		t.Fatalf("get unknown: %d", rec.Code)
	}
	if rec := do(h, "GET", "/api/campaigns/"+f.ID, "", nil); rec.Code != http.StatusUnauthorized {
		t.Fatalf("no token: %d", rec.Code)
	}

	rec := do(h, "GET", "/metrics", "", nil)
	if rec.Code != http.StatusOK {
		t.Fatalf("/metrics without a token: %d, want 200", rec.Code)
	}
	if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/plain") {
		t.Errorf("/metrics content type %q", ct)
	}
	body := rec.Body.String()
	for _, id := range []string{f.ID, unknown, f.Revision} {
		if strings.Contains(body, id) {
			t.Errorf("/metrics contains the id %s", id)
		}
	}
	s := metricstest.Parse(t, body)
	for _, v := range s.LabelValues() {
		if metricstest.IDShaped(v) {
			t.Errorf("label value %q looks like an id", v)
		}
	}
	route := "route=GET /api/campaigns/{id}"
	for _, w := range []struct {
		status string
		n      float64
	}{{"200", 1}, {"404", 1}, {"401", 1}} {
		if got := s.Get("http_requests_total", route, "status="+w.status); got != w.n {
			t.Errorf("http_requests_total{%s,status=%s} = %v, want %v", route, w.status, got, w.n)
		}
	}
	// An unmatched path is one label value, not one per path.
	do(h, "GET", "/no/such/"+f.ID, "", bearer)
	do(h, "GET", "/no/such/other", "", bearer)
	s = metricstest.Scrape(t, h)
	for k := range s {
		if strings.HasPrefix(k, "http_requests_total") && strings.Contains(k, "/no/such") {
			t.Errorf("unmatched path became a label: %s", k)
		}
	}
}

// sse_streams counts open event streams and goes back down when one ends.
func TestMetricsSSEStreams(t *testing.T) {
	url, meta := testdb.Seeded(t)
	p := pool(t, url)
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	reg := metrics.New()
	srv := httptest.NewServer(handler(t, &Server{
		Config:    Config{AdminToken: token, CampaignURLHosts: []string{"shop.example"}},
		Pool:      p,
		Now:       func() time.Time { return meta.AsOf },
		Hub:       NewHub(ctx, p, slog.New(slog.DiscardHandler)),
		Heartbeat: time.Second,
		Metrics:   reg,
	}))
	t.Cleanup(srv.Close)
	id := eventCampaign(t, p)
	_, frames := openStream(t, srv, "/api/campaigns/"+id+"/events", bearer)
	addGenEvent(t, p, id, "started", map[string]any{})
	sseNext(t, frames, 4*time.Second)
	if n := metricstest.Scrape(t, reg.Handler()).Get("sse_streams"); n != 1 {
		t.Errorf("one open stream: sse_streams = %v", n)
	}
	addGenEvent(t, p, id, "done", map[string]any{})
	sseEnded(t, frames, 4*time.Second)
	deadline := time.Now().Add(2 * time.Second)
	for metricstest.Scrape(t, reg.Handler()).Get("sse_streams") != 0 {
		if time.Now().After(deadline) {
			t.Fatal("sse_streams did not go back to 0 after the stream ended")
		}
		time.Sleep(20 * time.Millisecond)
	}
}
//go:build spec

package main

import (
	"context"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/metrics/metricstest"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// Plan 3, 3.3. The app image is distroless, so compose healthchecks run
// "app healthcheck <url>": one GET with a 2 s timeout, exit 0 on 200, else
// 1. healthcheckCmd(args) returns the exit code; a missing URL is a usage
// error, 2.
func TestHealthcheckExitCodes(t *testing.T) {
	ok := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.WriteHeader(http.StatusMethodNotAllowed)
		}
	}))
	t.Cleanup(ok.Close)
	unavailable := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusServiceUnavailable)
	}))
	t.Cleanup(unavailable.Close)
	redirect := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, ok.URL, http.StatusFound)
	}))
	t.Cleanup(redirect.Close)
	hang := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		<-r.Context().Done()
	}))
	t.Cleanup(hang.Close)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	refused := "http://" + ln.Addr().String() + "/readyz"
	ln.Close()

	cases := []struct {
		name string
		args []string
		want int
	}{
		{"200", []string{ok.URL + "/readyz"}, 0},
		{"503", []string{unavailable.URL + "/readyz"}, 1},
		{"refused", []string{refused}, 1},
		{"redirect is not 200", []string{redirect.URL}, 1},
		{"no url", nil, 2},
		{"two urls", []string{ok.URL, ok.URL}, 2},
	}
	for _, c := range cases {
		if got := healthcheckCmd(c.args); got != c.want {
			t.Errorf("%s: exit %d, want %d", c.name, got, c.want)
		}
	}

	start := time.Now()
	if got := healthcheckCmd([]string{hang.URL}); got != 1 {
		t.Errorf("hanging server: exit %d, want 1", got)
	}
	if d := time.Since(start); d > 3*time.Second {
		t.Errorf("hanging server: took %v, want the 2 s timeout", d)
	}
}

// The worker serves /healthz, /readyz and /metrics on WORKER_METRICS_ADDR.
// /readyz is 200 once River has started and the database answers, and
// stops being 200 when the worker stops.
func TestWorkerHealthAndMetrics(t *testing.T) {
	url, _ := testdb.Seeded(t)
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := ln.Addr().String()
	ln.Close()
	base := "http://" + addr

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	done := make(chan error, 1)
	go func() {
		done <- workerCmd(ctx, quiet, env(map[string]string{"LLM_MODE": "mock", "DATABASE_URL": url,
			"PROVIDER_URL": "http://127.0.0.1:9", "WORKER_METRICS_ADDR": addr}))
	}()

	get := func(path string) (int, string) {
		c := &http.Client{Timeout: time.Second}
		resp, err := c.Get(base + path)
		if err != nil {
			return 0, err.Error()
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		return resp.StatusCode, string(b)
	}
	waitFor := func(what string, cond func() bool) {
		t.Helper()
		deadline := time.Now().Add(15 * time.Second)
		for !cond() {
			if time.Now().After(deadline) {
				t.Fatalf("%s within 15s", what)
			}
			time.Sleep(50 * time.Millisecond)
		}
	}

	waitFor("/readyz 200", func() bool { code, _ := get("/readyz"); return code == http.StatusOK })
	if code, _ := get("/healthz"); code != http.StatusOK {
		t.Errorf("/healthz: %d", code)
	}
	code, body := get("/metrics")
	if code != http.StatusOK {
		t.Fatalf("/metrics: %d", code)
	}
	s := metricstest.Parse(t, body)
	if !s.Has("worker_last_processed_timestamp_seconds") {
		t.Error("worker /metrics has no worker_last_processed_timestamp_seconds")
	}
	for _, name := range s.Names() {
		if strings.HasPrefix(name, "http_requests_total") || name == "sse_streams" {
			t.Errorf("worker exposes the api series %s", name)
		}
	}

	cancel()
	waitFor("/readyz to stop being 200 after stop", func() bool { code, _ := get("/readyz"); return code != http.StatusOK })
	select {
	case err := <-done:
		if err != nil {
			t.Errorf("worker stopped with %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Error("worker did not stop")
	}
}

